#include "powder/bulk_process.hpp"
#include <iostream>
#include <fstream>
#include <iomanip>
#include <chrono>
#include <set>
using namespace powder;
void check(bool b,const char* s){if(!b)throw std::runtime_error(s);}
void valid(const BulkProcess& p){auto totals=p.graph.totals();for(unsigned g=0;g<3;++g)check(std::abs(totals[g]-p.initial[g])<1e-8,"powder mass conservation");for(const auto& node:p.graph.nodes){check(bulk_sum(node.mass)<=node.capacity+1e-8,"capacity");for(double m:node.mass)check(m>=0&&std::isfinite(m),"negative/nonfinite mass");}double initial=p.config.ambient_pa*p.config.gas_volume_m3/p.config.gas_rt;check(std::abs(p.pressure_pa*p.config.gas_volume_m3/p.config.gas_rt-(initial+p.gas_in_kg-p.gas_out_kg))<1e-9,"air mass conservation");check(p.pressure_pa>=p.config.pump_target_pa-1e-8&&p.pressure_pa<=p.config.ambient_pa+1e-8,"pressure bounds");}
BulkProcess finish(BulkProcessConfig c,double dt=.01){BulkProcess p(c);for(unsigned i=0;p.time<500&&p.phase!=BulkPhase::Complete;++i){p.advance(dt);if(i%100==0)valid(p);}check(p.phase==BulkPhase::Complete,"cycle timeout");valid(p);check(bulk_sum(p.mixer_mass())>.99*c.total_kg,"delivery shortfall");return p;}
int main(int argc,char** argv){try{
 BulkGraph g;g.nodes={{{3,2,1},10},{{0,0,0},2},{{0,0,0},10}};auto initial=g.totals();std::vector<BulkFlux> flows={{0,1,100,0},{0,2,100,0}};g.transfer(flows);check(g.totals()==initial&&bulk_sum(g.nodes[1].mass)<=2,"simultaneous allocation");auto before=g.nodes;bool rejected=false;flows={{0,99,1,0}};try{g.transfer(flows);}catch(const std::invalid_argument&){rejected=true;}check(rejected&&g.nodes[0].mass==before[0].mass,"invalid graph atomicity");
 BulkProcessConfig c;c.total_kg=10;BulkProcess p(c);p.controls.supply_enabled=false;for(unsigned i=0;i<100;++i)p.advance(.01);check(bulk_sum(p.graph.nodes[p.weigh].mass)==0,"disabled supply");p.controls.supply_enabled=true;p.controls.pump_enabled=false;while(p.phase!=BulkPhase::Transfer&&p.time<50)p.advance(.01);check(p.phase==BulkPhase::Transfer,"weigh controller transition");p.controls.pump_enabled=false;double held=bulk_sum(p.graph.nodes[p.weigh].mass);for(unsigned i=0;i<500;++i)p.advance(.01);check(std::abs(held-bulk_sum(p.graph.nodes[p.weigh].mass))<1e-12,"no pump transports mass");p.controls.pump_enabled=true;p.controls.transfer_open=false;auto travel=p.pipe_travel;for(unsigned i=0;i<200;++i)p.advance(.01);check(std::abs(held-bulk_sum(p.graph.nodes[p.weigh].mass))<1e-12,"closed transfer valve leaked");check(p.pipe_travel==travel,"closed valve moves visual flow");p.controls.transfer_open=true;while(p.phase!=BulkPhase::Mix&&p.time<300)p.advance(.01);check(p.phase==BulkPhase::Mix,"sequence did not reach mix");auto unmixed=p.graph.nodes;double oldMix=p.mix_time;p.controls.rpm=0;for(unsigned i=0;i<200;++i)p.advance(.01);for(unsigned i=0;i<24;++i)check(p.graph.nodes[p.mixer+i].mass==unmixed[p.mixer+i].mass,"stopped mixing changes composition");check(p.mix_time==oldMix,"stopped mixer completes timer");valid(p);
 auto a=finish(c,.01),b=finish(c,.0025);check(std::abs(a.time-b.time)<.1,"time refinement");check(std::abs(a.mixing_index()-b.mixing_index())<.01,"mix refinement");c.pipe_cells=48;auto refined=finish(c);check(std::abs(refined.time-a.time)/a.time<.1,"pipe resolution drift");

 BulkProcessConfig excess;c.pipe_cells=24;excess.total_kg=10;excess.reserve_factor=1.2;auto stopped=finish(excess);check(bulk_sum(stopped.mixer_mass())<10.1,"weigher fails to stop with excess stock");check(bulk_sum(stopped.graph.nodes[0].mass)>.5,"weigher emptied excess stock");
 BulkProcess fault(c);while(fault.phase!=BulkPhase::Dump&&fault.time<200)fault.advance(.01);check(fault.phase==BulkPhase::Dump,"dump transition");fault.controls.dump_open=false;auto receiver=fault.graph.nodes[fault.receiver].mass;for(unsigned i=0;i<100;++i)fault.advance(.01);check(receiver==fault.graph.nodes[fault.receiver].mass,"closed dump leaked");valid(fault);
 if(argc==2){std::ofstream out(argv[1]);out<<std::setprecision(17)<<"kg,rpm,repeat,physical_s,wall_s,rate,mixer_kg,mix_index,powder_error,gas_error\n";for(double kg:{10.,30.,50.})for(double rpm:{15.,30.,60.})for(unsigned repeat=0;repeat<3;++repeat){BulkProcessConfig cfg;cfg.total_kg=kg;cfg.rpm=rpm;auto start=std::chrono::steady_clock::now();auto result=finish(cfg);double wall=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();auto total=result.graph.totals();double error=0;for(unsigned j=0;j<3;++j)error=std::max(error,std::abs(total[j]-result.initial[j]));double gaserror=std::abs(result.pressure_pa*cfg.gas_volume_m3/cfg.gas_rt-(cfg.ambient_pa*cfg.gas_volume_m3/cfg.gas_rt+result.gas_in_kg-result.gas_out_kg));out<<kg<<','<<rpm<<','<<repeat<<','<<result.time<<','<<wall<<','<<result.time/wall<<','<<bulk_sum(result.mixer_mass())<<','<<result.mixing_index()<<','<<error<<','<<gaserror<<'\n';out.flush();}check(bool(out),"output error");}
 std::cout<<"PASS conservative graph, controller, pressure balance, interlocks, mixing, refinement, complete cycle\n";
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
